#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv) {
    /* ----- error handling ----- */
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }

    char *endptr = NULL;
    long n = strtol(argv[1], &endptr, 10);

    /* bad number (no digits) or extra characters */
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }

    if (n < 0) {                 /* negative size */
        puts("BAD_INPUT");
        return 0;
    }
    if (n == 0) {                /* zero rows */
        puts("EMPTY");
        return 0;
    }
    if (n > 60) {                /* the original program limited to 60 rows */
        puts("OUT_OF_RANGE");
        return 0;
    }

    /* ----- Pascal triangle generation ----- */
    long long row[61] = {0};   // current row values
    long long prev[61] = {0};  // previous row values

    prev[0] = 1;               // row 0 (not printed, start from row 0 in loop)

    for (int r = 0; r < n; ++r) {
        row[0] = 1;            // first element of every row
        for (int c = 1; c < r; ++c) {
            row[c] = prev[c - 1] + prev[c];
        }
        if (r > 0) {
            row[r] = 1;        // last element (only for rows > 0)
        }

        /* output the row */
        for (int c = 0; c <= r; ++c) {
            if (c > 0) putchar(' ');
            printf("%lld", row[c]);
        }
        putchar('\n');

        /* prepare for next iteration */
        memcpy(prev, row, sizeof(long long) * (r + 1));
    }
    return 0;
}
